const $=id=>document.getElementById(id), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function normalizeMood(value){return ({'\u597d\u5947':'Curious','\u8ff7\u832b':'Uncertain','\u671f\u5f85':'Hopeful','\u75b2\u60eb':'Tired','\u5e73\u9759':'Calm'})[value]||value||'Curious'}
function normalizeFormat(value){return ({'\u4e2a\u4eba\u6545\u4e8b':'Personal Story','\u5206\u955c\u811a\u672c':'Storyboard','Visual narrative':'Storyboard','\u8bd7 / \u6587\u6848':'Poem / Short Text','\u89d2\u8272\u6545\u4e8b':'Character Story'})[value]||value||'Personal Story'}
let size=1,mood='Curious',drawn=[],focus=0,symbol=0,format='Personal Story',context=null;
let perspective='upright',fit='';
const formats=['Personal Story','Storyboard','Journal','Poem / Short Text','Character Story','Tarot Story Card'];
let archive=[];try{const raw=JSON.parse(localStorage.getItem('arcana-stories-v1')||'[]');archive=Array.isArray(raw)?raw.filter(x=>x&&typeof x.text==='string'&&typeof x.title==='string'&&Array.isArray(x.cards)).map(x=>({...x,format:normalizeFormat(x.format),cards:x.cards.map(c=>({...c,name:CARDS.find(card=>card.id===c.id)?.name||c.name}))})):[]}catch{}
function switchView(v){['studio','library','saved'].forEach(x=>$(x).hidden=x!==v);document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.view===v));if(v==='saved')renderSaved();window.scrollTo({top:0,behavior:'smooth'})}
document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>switchView(b.dataset.view));
document.querySelectorAll('[data-size]').forEach(b=>b.onclick=()=>{if(size===+b.dataset.size)return;size=+b.dataset.size;document.querySelectorAll('[data-size]').forEach(x=>x.classList.toggle('selected',x===b));drawn=[];focus=0;symbol=0;invalidate();$('expression').hidden=true;$('express').hidden=true;$('draw').textContent='✦ Tap a card to begin';$('draw-status').textContent='Choose one card, or let three unfold a journey.';$('stage-hint').textContent='Draw, then explore';renderSpread()});
document.querySelectorAll('[data-mood]').forEach(b=>b.onclick=()=>{if(mood===b.dataset.mood)return;mood=b.dataset.mood;document.querySelectorAll('[data-mood]').forEach(x=>x.classList.toggle('selected',x===b));invalidate()});
$('question').oninput=invalidate;
function invalidate(){$('reading').hidden=true;if(context){feedback('Your context or cards changed. Your story is safe; connect your new context to create a new draft.')}persistDraft()}
function position(i){return drawn.length===1?'THE MOMENT':['WHAT I BRING','WHAT I AM IN','WHAT I CAN EXPLORE'][i]}
function renderSpread(){
 $('draw-entry').prepend($('reverse-toggle'));$('reverse-caption').textContent='Include a reversed perspective for the same card';
 if(!drawn.length){$('spread').classList.remove('has-three');$('spread').innerHTML=Array.from({length:size},(_,i)=>`<div class="card-wrap"><div class="card-position">${size===1?'THE MOMENT':['WHAT I BRING','WHAT I AM IN','WHAT I CAN EXPLORE'][i]}</div><button class="art card-back" type="button" data-draw-back aria-label="Tap the card back to draw"><span class="back-orbit"></span><span class="back-star">✳</span><span class="back-word">BEYOND</span></button><p class="card-name">A story waiting for you</p><span class="card-en">A STORY WAITING TO UNFOLD</span></div>`).join('');document.querySelectorAll('[data-draw-back]').forEach(b=>b.onclick=()=>{if(!drawing)$('draw').click()});$('insight').hidden=true;$('personal-observation').hidden=true;$('connections').hidden=true;return}
 $('insight').hidden=false;$('personal-observation').hidden=false;$('connections').hidden=false;$('spread').innerHTML=drawn.map((c,i)=>`<div class="card-wrap"><div class="card-position">${position(i)}</div><div class="art ${c.reversed?'reverse':''}"><img src="assets/${c.id}.jpg" alt="${c.name} card image${c.reversed?'Reversed':''}">${c.symbols.map((s,j)=>s.scene?'':`<button class="hotspot ${focus===i&&symbol===j?'selected':''}" style="left:${c.reversed?100-Number(s.x):s.x}%;top:${c.reversed?100-Number(s.y):s.y}%" aria-label="Explore ${esc(s.name)}" data-card="${i}" data-symbol="${j}">✦</button>`).join('')}</div><p class="card-name">${c.name} <small>${c.reversed?'Reversed':'Upright'}</small></p><span class="card-en">${c.en}</span>${c.symbols.some(s=>s.scene)?`<button class="scene-open" data-scene="${i}" aria-label="Explore the scene of ${c.name}">✦ Explore the scene</button>`:''}</div>`).join('');document.querySelectorAll('.hotspot').forEach(b=>b.onclick=()=>{focus=+b.dataset.card;symbol=+b.dataset.symbol;fit='';invalidate();renderSpread()});document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>openScene(+b.dataset.scene));renderInsight();renderConnections()}
function reverseEnabled(){return $('reversed').checked}
function reverseBlock(c){return `<div class="reverse-reading"><p class="eyebrow">SAME CARD / REVERSED PERSPECTIVE</p><h3>${esc(c.name)}: ${esc(c.reverse)}</h3><p>Another possibility to explore: ${esc(c.reverse)}. This is a teaching hypothesis, not evidence about your life.</p><p><b>Reflect and adjust</b><br>${esc(c.reverseAction)}. </p><p class="small muted">Reversed does not mean bad. Compare perspectives and keep what fits your situation.</p></div>`}
function renderConnections(){if(drawn.length!==3){$('connections').innerHTML=drawn[0].symbols.length>1?'One card, many perspectives. Explore another symbol to find a different story.':'Describe what you see before connecting it to your own world.';return}
 $('connections').innerHTML=`<b>Upright story arc</b><br>${drawn.map(c=>esc(c.theme)).join(' → ')}<br>Three positions form a narrative path.${reverseEnabled()?`<div class="reverse-chain"><b>Reversed perspective · Same spread</b><br>${drawn.map(c=>esc(c.reverse)).join(' → ')}<br>Consider how blocked or inward processes might form an alternative story.</div>`:''}`;
}
function renderInsight(){$('draw-entry').prepend($('reverse-toggle'));const c=drawn[focus],s=c.symbols[symbol];$('insight').innerHTML=`<div class="insight-heading"><h3>${esc(c.name)} · ${esc(s.name)}</h3><div class="insight-tools"><span class="eyebrow">SEE → UNDERSTAND</span><div id="insight-reverse-slot"></div></div></div><p class="observation"><b>What you can see</b><br>${esc(c.observation||s.name)}</p><div class="perspectives" role="group" aria-label="Choose a perspective"><button data-perspective="upright" aria-pressed="${perspective==='upright'}">Upright</button>${reverseEnabled()?`<button data-perspective="reverse" aria-pressed="${perspective==='reverse'}">Reversed</button>`:''}<button data-perspective="personal" aria-pressed="${perspective==='personal'}">My associations</button></div><div class="chosen-perspective">${perspective==='reverse'?reverseBlock(c):perspective==='personal'?'<h3>Give this scene your own meaning</h3><p>Write your associations below. Your words will shape the story; you can choose your own meaning.</p>':`<p><b>Teaching perspective / ${esc(c.theme)}</b><br>${esc(s.meaning)}. Consider this a visual clue for “${esc(c.theme)}”.</p>`}</div><div class="fit-controls"><button data-fit="Fits me" aria-pressed="${fit==='Fits me'}">Fits me ✓</button><button data-fit="Another angle" aria-pressed="${fit==='Another angle'}">Another angle ↻</button></div><p class="small muted" role="status">${fit==='Fits me'?'Perspective selected. Next, bring in your context.':fit==='Another angle'?'Try this angle, or write your own associations below.':'Choose a perspective that fits, then add an observation or association.'}</p><p class="small muted">Source: ${esc(c.learningSource||'Original teaching library')}. Perspectives support reflection; they do not establish facts or predict the future.</p>`;$('insight-reverse-slot').append($('reverse-toggle'));$('reverse-caption').textContent='Reversed view';document.querySelectorAll('[data-perspective]').forEach(b=>b.onclick=()=>{perspective=b.dataset.perspective;fit='';invalidate();renderInsight()});document.querySelectorAll('[data-fit]').forEach(b=>b.onclick=()=>{fit=b.dataset.fit;if(fit==='Another angle')perspective=perspective==='upright'?(reverseEnabled()?'reverse':'personal'):perspective==='reverse'?'personal':'upright';invalidate();renderInsight()})}
$('reversed').onchange=()=>{if(reverseEnabled()&&drawn.length)perspective='reverse';else if(!reverseEnabled()&&perspective==='reverse')perspective='upright';if(drawn.length){renderInsight();renderConnections()}invalidate();$('draw-status').textContent=reverseEnabled()?'A reversed perspective is available for the same card. Choose what fits your story.':'Reversed comparison is closed. Your cards are unchanged.'};

function random(n){const b=new Uint32Array(1);crypto.getRandomValues(b);return Math.floor(b[0]/4294967296*n)}
let drawing=false;
$('draw').onclick=()=>{
 if(drawing)return;
 const previousFirst=drawn[0]?.id,pool=[...CARDS];
 drawn=Array.from({length:size},(_,i)=>{const choices=i===0?pool.filter(c=>c.id!==previousFirst):pool;const card=choices[random(choices.length)];pool.splice(pool.findIndex(c=>c.id===card.id),1);return {...card,reversed:false}});
 focus=0;symbol=0;perspective='upright';fit='';invalidate();renderSpread();$('expression').hidden=true;
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 document.querySelectorAll('#spread .art').forEach((art,i)=>{art.style.animationDelay=(reduced?0:i*140)+'ms';art.classList.add('reveal')});
 $('draw-status').textContent='Drawn: '+drawn.map(c=>c.name+' ('+(c.reversed?'Reversed':'Upright')+')').join(', ')+'. Explore a symbol or scene, then add your context.';
 $('stage-hint').textContent='Explore visual clues';$('express').hidden=false;$('draw').textContent=drawn.length===1?'↻ Draw another card':'↻ Draw another spread';
 persistDraft();drawing=true;$('draw').disabled=true;setTimeout(()=>{drawing=false;$('draw').disabled=false},reduced?0:650+(size-1)*140);
};
$('express').onclick=()=>{$('expression').hidden=false;persistDraft();$('question').focus({preventScroll:true});$('expression').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})};
$('close-expression').onclick=()=>{$('expression').hidden=true;persistDraft();$('express').focus({preventScroll:true})};
function renderReading(){if(!context)return;const {question:q,mood:m,cards:cs,focus:f,symbol:j,includeReversed}=context,s=cs[f].symbols[j];$('reading').hidden=false;$('reading').innerHTML=`<p class="eyebrow">02 / PERSONAL INTERPRETATION · LOCAL DEMO</p><h2>From ${esc(s.name)} to your own perspective.</h2><p>Your context: <strong>${esc(q)}</strong></p>${cs.map((c,i)=>`<article class="card-reading"><p><b>${cs.length===1?'The moment':['What I bring','What I am in','What I can explore'][i]} · ${esc(c.name)} / Upright</b><br>${esc(i===f?s.name:c.symbols[0].name)} can be a metaphor for ${esc(c.theme.toLowerCase())}. Feeling ${esc(m.toLowerCase())}, you might try this: ${esc(c.action)} Keep or rewrite the perspective that fits you.</p>${includeReversed?`<div class="reverse-reading"><p class="eyebrow">SAME CARD / REVERSED VIEW</p><p><b>${esc(c.name)} · ${esc(c.reverse)}</b><br>In your situation, ask whether this perspective fits. The card does not prove that it is true.</p><p><b>Reflect and adjust</b><br>${esc(c.reverseAction)}</p></div>`:''}</article>`).join('')}${cs.length===3?`<p><b>Relationships between the cards</b><br>${cs.map(c=>esc(c.theme)).join(' → ')}. Read the positions as a starting point, an experience and a direction to explore.</p>${includeReversed?`<p><b>Alternative arc · Same cards</b><br>${cs.map(c=>esc(c.reverse)).join(' → ')}. Consider obstacles, excess or an inward adjustment alongside the upright arc.</p>`:''}`:''}<p><b>Your chosen perspective</b>: ${esc({upright:'Upright',reverse:'Reversed',personal:'My associations'}[context.perspective]||'Upright')}</p>${context.observation?`<p><b>Your observation</b>: ${esc(context.observation)}</p>`:''}${context.association?`<p><b>Your association</b>: ${esc(context.association)}</p>`:''}<p class="source">This is a local, rule-based learning example. AI is not connected. Comparing perspectives does not change the cards.</p>`}
$('interpret').onclick=()=>{const q=$('question').value.trim();if(!q){$('question').focus();$('question').placeholder='Write a question, feeling or story idea to connect with the cards.';return}if(!mayReplace())return;checkpoint();context={question:q,mood,cards:drawn.map(c=>({...c})),focus,symbol,includeReversed:reverseEnabled(),perspective,fit,observation:$('observation').value.trim(),association:$('association').value.trim()};renderReading();$('creation').hidden=false;format='Personal Story';renderFormats();generate();$('reading').scrollIntoView({behavior:'smooth',block:'start'})};

function renderFormats(){const button=f=>`<button class="${f===format?'selected':''}" data-format="${f}" aria-pressed="${f===format}">${f}</button>`;$('formats').innerHTML=formats.slice(0,2).map(button).join('');$('extra-formats').innerHTML=formats.slice(2).map(button).join('');$('more-formats').open=formats.indexOf(format)>1;document.querySelectorAll('[data-format]').forEach(b=>b.onclick=()=>{if(format===b.dataset.format)return;if(!mayReplace())return;checkpoint();format=b.dataset.format;renderFormats();generate()})}
let lastGenerated='',lastGeneratedTitle='';
function generate(){if(!context)return;const {question:q,mood:m,cards:cs,focus:f,symbol:j}=context,c=cs[f],s=c.symbols[j],tone=$('rewrite').value,ending={gentle:'I give myself permission to move slowly. This story does not need an immediate answer, only space for an honest feeling.',brave:'Today I choose one small step, giving my idea a shape I can see.',dream:'Distant light turns the path silver. An unwritten page unfolds softly in the wind.'}[tone],theme=context.perspective==='reverse'?c.reverse:c.theme,path=cs.map(x=>context.perspective==='reverse'?x.reverse:x.theme).join(' → '),opening=`I enter this story with a question: “${q}” Right now, I feel ${m.toLowerCase()}.`,middle=context.perspective==='personal'?`I begin with ${s.name.toLowerCase()} in ${c.name}, and let my own association guide the story: ${context.association||'What this scene means to me is still mine to explore.'}`:`${s.name} in ${c.name} brings ${context.perspective==='reverse'?c.reverse.toLowerCase():s.meaning.toLowerCase()} to mind. I am exploring a perspective, rather than seeking a certain ending.`,multi=cs.length===3?`The story follows “${path}”: ${cs[0].name} offers a beginning, ${cs[1].name} introduces an experience, and ${cs[2].name} leaves a direction to explore.`:'';let text='',title='A story beginning with '+s.name.toLowerCase();
if(format==='Personal Story')text=[opening,middle,multi,ending].filter(Boolean).join('\n\n');
if(format==='Storyboard'){title='Three scenes from my world';text=`SCENE 01 / An entrance\nContext: ${q}\nClose-up: ${s.name}. Use light and framing to explore ${s.meaning.toLowerCase()}.\n\nSCENE 02 / Meeting the symbols\n${cs.map((x,i)=>`Shot ${i+1}: ${x.symbols[0].name} in ${x.name}. The character explores ${context.perspective==='reverse'?x.reverse.toLowerCase():x.theme.toLowerCase()}.`).join('\n')}\n\nSCENE 03 / To be continued\n${ending}\n\nStoryboard text only. Images and video are not generated.`}
if(format==='Journal'){title='What I noticed today';text=`My context\n${q}\n\nHow I feel\n${m}\n\nThe symbol I noticed\n${c.name} · ${s.name}: ${s.meaning}\n\nHow does this connect to my life?\n${middle}\n\nOne step I am willing to try\n${cs[cs.length-1].action}\n\nA note to myself\n${ending}`}
if(format==='Poem / Short Text'){title='A note to my '+m.toLowerCase()+' self';text=`For “${q}”\n\nI place my ${m.toLowerCase()} feeling in a card,\nand let ${s.name.toLowerCase()} hold a little light.\n${s.meaning},\na thought I had not yet put into words.\n\n${cs.length===3?cs.map(x=>x.theme+',').join('\n'):'I pause with '+theme.toLowerCase()+','}\n${ending}`}
if(format==='Character Story'){title='The '+c.archetype+"'s next chapter";text=`Character: A ${c.archetype} feeling ${m.toLowerCase()}.\nWish: ${q}\nAn object they carry: ${s.name}, suggesting ${s.meaning.toLowerCase()}.\n\n${cs.length===3?`They encounter ${cs[0].name}, enter the scene of ${cs[1].name}, and arrive at a crossroads left by ${cs[2].name}.`:`They enter the scene of ${c.name}, exploring ${theme.toLowerCase()}.`}\n\nTheir next action: ${cs[cs.length-1].action}\nTheir words: “${ending}”`}
if(format==='Tarot Story Card'){title='My story, in my own words';text=`${q}\n\nFeeling: ${m}\nStory arc: ${path}\n\n${s.name} brings to mind ${s.meaning.toLowerCase()}.\n\n${ending}`}
const personal=[context.observation?'I notice: '+context.observation:'',context.association?'This reminds me of: '+context.association:''].filter(Boolean).join('\n');
if(personal){if(format==='Storyboard')text=text.replace('SCENE 02 /',personal+'\n\nSCENE 02 /');else text=personal+'\n\n'+text}
if(context.perspective==='reverse'){const conflict=cs.map(x=>x.reverse).join(' → ');if(format==='Poem / Short Text')text+='\n\n'+conflict+',\nI leave room for hesitation,\nand for a different way forward.';else if(format==='Storyboard')text=text.replace('SCENE 03 /','Inner tension: '+conflict+'. Show this through pauses, distance and light.\n\nSCENE 03 /');else if(format==='Character Story')text+='\n\nTheir inner tension: '+conflict+'. They consider this adjustment: '+cs[cs.length-1].reverseAction;else if(format==='Journal')text+='\n\nAnother possibility to examine\n'+conflict+'\nAn adjustment to consider: '+cs[cs.length-1].reverseAction;else text+='\n\nI also consider '+conflict.toLowerCase()+'. A possible adjustment: '+cs[cs.length-1].reverseAction}
$('output-title').value=title;$('output').value=text;lastGenerated=text;lastGeneratedTitle=title;$('mini-cards').innerHTML=cs.map(c=>`<img src="assets/${c.id}.jpg" alt="${c.name}" style="${c.reversed?'transform:rotate(180deg)':''}">`).join('');$('story-date').textContent=new Date().toLocaleDateString('en-US');$('feedback').textContent='';persistDraft();}
$('remix').onclick=()=>{if(!mayReplace())return;checkpoint();generate()};
function feedback(t){$('feedback').textContent=t}
$('save').onclick=()=>{if(!context)return;const entry={id:Date.now(),title:$('output-title').value,text:$('output').value,format,context,tone:$('rewrite').value,date:new Date().toISOString(),cards:context.cards.map(c=>({name:c.name,id:c.id,reversed:c.reversed}))};try{const next=[entry,...archive];localStorage.setItem('arcana-stories-v1',JSON.stringify(next));archive=next;updateCount();feedback('Saved, including your edits.')}catch{feedback('Browser storage is unavailable or full. Download your story to keep it.')}};
function updateCount(){$('count').textContent=archive.length}
function renderSaved(){$('saved-list').innerHTML=archive.length?archive.map(e=>`<article class="saved-item"><p class="eyebrow">${esc(e.format||'Story')} · ${esc(new Date(e.date).toLocaleDateString('en-US'))}</p><h2>${esc(e.title)}</h2><p>${esc(e.cards.map(c=>c.name+' · '+(c.reversed?'Reversed':'Upright')).join(' · '))}</p><div>${esc(e.text)}</div><button class="secondary" data-edit="${e.id}">Continue editing ↗</button><button class="secondary" data-export="${e.id}">Download story card ↓</button><button class="text-button" style="display:inline" data-delete="${e.id}">Delete</button></article>`).join(''):'<div class="empty">Your first story is waiting.<br>Return to the studio, draw a card and leave your own words.<br><button class="secondary" id="empty-start">Start creating ↗</button></div>';document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{if(!mayReplace())return;checkpoint();const e=archive.find(x=>x.id===+b.dataset.edit);applyDraft({cards:e.cards,context:e.context||{question:e.text,mood:'Curious',cards:e.cards,focus:0,symbol:0,includeReversed:false},question:e.context?.question||'',mood:e.context?.mood||'Curious',format:e.format,title:e.title,text:e.text,lastGenerated:e.text,tone:e.tone||'gentle',reversed:e.context?.includeReversed||false});persistDraft();switchView('studio')});if($('empty-start'))$('empty-start').onclick=()=>switchView('studio');document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(!confirm('Delete this saved story?'))return;const next=archive.filter(e=>e.id!==+b.dataset.delete);try{localStorage.setItem('arcana-stories-v1',JSON.stringify(next));archive=next;updateCount();renderSaved()}catch{alert('Could not delete: browser storage is unavailable.')}});document.querySelectorAll('[data-export]').forEach(b=>b.onclick=async()=>{const e=archive.find(x=>x.id===+b.dataset.export);b.disabled=true;try{await exportCard(e.title,e.text,e.cards,e.context?.association||e.context?.observation||'');b.textContent='Download started ↓'}catch{b.textContent='Could not generate. Try again'}finally{b.disabled=false}})}
async function exportCard(title,text,cards,personal=''){const images=await Promise.all(cards.map(async c=>{if(!CARDS.some(x=>x.id===c.id))throw Error('Card not found');const response=await fetch('assets/'+c.id+'.jpg');if(!response.ok)throw Error('Could not load card image');const bytes=new Uint8Array(await response.arrayBuffer());let raw='';for(const byte of bytes)raw+=String.fromCharCode(byte);return 'data:image/jpeg;base64,'+btoa(raw)}));const svg=buildStorySvg(title,text,cards,images,personal);const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='Beyond-the-Cards-Story.svg';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}
$('download').onclick=async()=>{if(!context)return;$('download').disabled=true;feedback('Preparing your illustrated story card…');try{await exportCard($('output-title').value,$('output').value,context.cards,context.association||context.observation||'');feedback('Your story card is ready. Check your browser downloads.')}catch{feedback('Could not generate the card. Try again; your story is safe.')}finally{$('download').disabled=false}};
$('copy').onclick=async()=>{try{await navigator.clipboard.writeText($('output-title').value+'\n\n'+$('output').value);feedback('Copied. Your story is ready to share.')}catch{ $('output').focus();$('output').select();feedback('Use your system copy command to copy the selected text.')}};
let libraryCategory='All';
function renderLibrary(){const query=$('library-search').value.trim().toLowerCase();const filtered=[...CARDS].sort((a,b)=>a.order-b.order).filter(c=>(libraryCategory==='All'||c.category===libraryCategory)&&(!query||[c.name,c.en,c.theme,c.observation].join(' ').toLowerCase().includes(query)));
 $('library-count').textContent='Showing '+filtered.length+' / 78 cards';
 $('library-grid').innerHTML=filtered.length?filtered.map(c=>`<article class="library-item"><p class="eyebrow">${esc(c.category)}</p><img src="assets/${c.id}.jpg" alt="${c.name} card image" loading="lazy"><h3>${c.name}</h3><p class="library-observation">${esc(c.observation)}</p><p class="library-theme">${esc(c.theme)}</p><button class="secondary" data-explore="${c.id}">Explore this card ↗</button></article>`).join(''):'<div class="empty">No cards found. Try another keyword.</div>';
 document.querySelectorAll('[data-explore]').forEach(b=>b.onclick=()=>{drawn=[{...CARDS[+b.dataset.explore],reversed:false}];size=1;document.querySelectorAll('[data-size]').forEach(x=>x.classList.toggle('selected',x.dataset.size==='1'));focus=0;symbol=0;perspective='upright';fit='';invalidate();renderSpread();$('expression').hidden=true;$('express').hidden=false;$('draw').textContent='↻ Draw another card';$('draw-status').textContent='Selected: '+drawn[0].name+'. Explore the scene, then add your context.';$('stage-hint').textContent='Explore visual clues';switchView('studio')});
}
document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{libraryCategory=b.dataset.category;document.querySelectorAll('[data-category]').forEach(x=>x.classList.toggle('selected',x===b));renderLibrary()});$('library-search').oninput=renderLibrary;renderLibrary();updateCount();renderSpread();

function openScene(i){focus=i;symbol=0;fit='';invalidate();renderSpread();$('draw-status').textContent='Exploring '+drawn[i].name+'. The perspective appears below the card.'}

function mayReplace(){return !$('output').value||($('output').value===lastGenerated&&$('output-title').value===lastGeneratedTitle)||confirm('You edited this story. Replace it? You can restore the previous draft.')}
function draftSnapshot(){return {version:1,cards:drawn.map(c=>({id:c.id,reversed:c.reversed})),size,focus,symbol,question:$('question').value,mood,format,context,title:$('output-title').value,text:$('output').value,lastGenerated,lastGeneratedTitle,tone:$('rewrite').value,reversed:reverseEnabled(),perspective,fit,observation:$('observation').value,association:$('association').value,expression:!$('expression').hidden}}
function persistDraft(){try{localStorage.setItem('arcana-draft-v1',JSON.stringify(draftSnapshot()));$('draft-status').textContent='Draft saved in this browser'}catch{$('draft-status').textContent='Draft could not be saved. Save or download your story.'}}
function checkpoint(){if(!$('output').value)return;try{localStorage.setItem('arcana-draft-previous-v1',JSON.stringify(draftSnapshot()));$('restore-draft').hidden=false}catch{}}
function applyDraft(d){const hydrate=cs=>(cs||[]).map(c=>CARDS.find(x=>x.id===c.id)).filter(Boolean).map(c=>({...c,reversed:false}));drawn=hydrate(d.cards);size=drawn.length===3||(!drawn.length&&d.size===3)?3:1;focus=Math.min(d.focus||0,Math.max(0,drawn.length-1));symbol=Math.min(d.symbol||0,Math.max(0,(drawn[focus]?.symbols.length||1)-1));mood=normalizeMood(d.mood);format=formats.includes(normalizeFormat(d.format))?normalizeFormat(d.format):'Personal Story';$('question').value=d.question||'';perspective=d.perspective||d.context?.perspective||'upright';fit=({'\u8d34\u8fd1\u6211':'Fits me','\u6362\u4e2a\u89d2\u5ea6':'Another angle'})[d.fit||d.context?.fit]||d.fit||d.context?.fit||'';$('observation').value=d.observation??d.context?.observation??'';$('association').value=d.association??d.context?.association??'';$('reversed').checked=!!d.reversed;$('rewrite').value=d.tone||'gentle';if(perspective==='reverse'&&!reverseEnabled())perspective='upright';context=d.context?{...d.context,mood:normalizeMood(d.context.mood),cards:hydrate(d.context.cards)}:null;if(!context?.cards.length)context=null;if(context){context.focus=Math.min(context.focus||0,context.cards.length-1);context.symbol=Math.min(context.symbol||0,context.cards[context.focus].symbols.length-1)}document.querySelectorAll('[data-size]').forEach(x=>x.classList.toggle('selected',+x.dataset.size===size));document.querySelectorAll('[data-mood]').forEach(x=>x.classList.toggle('selected',x.dataset.mood===mood));renderSpread();$('expression').hidden=!drawn.length||!d.expression;$('express').hidden=!drawn.length;if(drawn.length){$('draw').textContent=size===1?'↻ Draw another card':'↻ Draw another spread';$('draw-status').textContent='Your cards and draft have been restored.'}$('creation').hidden=!context;if(context){renderFormats();$('output-title').value=d.title||'My Stories';$('output').value=d.text||'';lastGenerated=d.lastGenerated||'';lastGeneratedTitle=d.lastGeneratedTitle||d.title||'';$('mini-cards').innerHTML=context.cards.map(c=>`<img src="assets/${c.id}.jpg" alt="${esc(c.name)}">`).join('');$('story-date').textContent=new Date().toLocaleDateString('en-US');$('reading').hidden=true;feedback('Story restored. It uses the cards shown in its thumbnails. Connect your current context for a new draft.')}}
$('output').oninput=persistDraft;$('output-title').oninput=persistDraft;$('observation').oninput=invalidate;$('association').oninput=invalidate;
$('rewrite').onchange=persistDraft;
$('restore-draft').onclick=()=>{if(!mayReplace())return;try{const d=JSON.parse(localStorage.getItem('arcana-draft-previous-v1')||'null');if(d){const current=draftSnapshot();applyDraft(d);localStorage.setItem('arcana-draft-previous-v1',JSON.stringify(current));persistDraft();feedback('Previous draft restored.')}}catch{feedback('Could not restore this draft.')}};
try{const d=JSON.parse(localStorage.getItem('arcana-draft-v1')||'null');if(d?.version===1)applyDraft(d);$('restore-draft').hidden=!localStorage.getItem('arcana-draft-previous-v1')}catch{}
window.addEventListener('pagehide',persistDraft);

function wrapStoryText(value,maxUnits){const width=s=>Array.from(s).reduce((n,c)=>n+(c.codePointAt(0)<128?.6:1),0),lines=[];String(value).split('\n').forEach(line=>{let current='';for(const char of Array.from(line)){if(width(current+char)>maxUnits&&current){const cut=current.lastIndexOf(' ');if(cut>0){lines.push(current.slice(0,cut));current=current.slice(cut+1)}else{lines.push(current);current=''}}current+=char}lines.push(current.trimEnd())});return lines}
function buildStorySvg(title,text,cards,images,personal=''){let y=142;const content=[];const add=(value,size,units)=>{for(const line of wrapStoryText(value,units)){content.push(`<text x="65" y="${y}" font-size="${size}">${esc(line)}</text>`);y+=size*1.6}y+=15};add(title,30,21);const cardY=y;cards.forEach((c,i)=>{const x=65+i*224;content.push(`<image x="${x}" y="${cardY}" width="150" height="250" preserveAspectRatio="xMidYMid meet" href="${esc(images[i])}"/><text x="${x}" y="${cardY+278}" font-size="17">${esc(c.name)} · ${c.reversed?'Reversed':'Upright'}</text>`)});y+=315;if(personal)add('My words: '+personal,19,33);add(text,22,29);const height=Math.ceil(Math.max(760,y+95));return `<svg xmlns="http://www.w3.org/2000/svg" width="800" height="${height}" viewBox="0 0 800 ${height}"><rect width="800" height="${height}" fill="#edf0e4"/><rect x="30" y="30" width="740" height="${height-60}" rx="8" fill="none" stroke="#b1bc9f"/><g fill="#294b3d" font-family="sans-serif"><text x="65" y="90" font-size="18" letter-spacing="3">BEYOND THE CARDS / YOUR STORY</text>${content.join('')}<text x="65" y="${height-65}" font-size="14">Made of symbols. Written by you.</text></g></svg>`}
